CREATE TABLE Kunde (KID INTEGER PRIMARY KEY, Name VARCHAR(60) NOT NULL, Ort VARCHAR(40), Email VARCHAR(80));
CREATE TABLE Artikel (ArtNr INTEGER PRIMARY KEY, Bezeichnung VARCHAR(60) NOT NULL, Kategorie VARCHAR(30), Preis DECIMAL(8,2));
CREATE TABLE Bestellung (BID INTEGER PRIMARY KEY, KID INTEGER NOT NULL REFERENCES Kunde(KID), Datum DATE, Status VARCHAR(20));
CREATE TABLE Position (BID INTEGER REFERENCES Bestellung(BID), ArtNr INTEGER REFERENCES Artikel(ArtNr), Menge INTEGER, PRIMARY KEY (BID, ArtNr));
CREATE TABLE Mitarbeiter (MID INTEGER PRIMARY KEY, Name VARCHAR(60), Abteilung VARCHAR(30), ChefID INTEGER REFERENCES Mitarbeiter(MID));
CREATE TABLE Konto (Nr INTEGER PRIMARY KEY, Inhaber VARCHAR(60), Saldo DECIMAL(10,2));
